SELECT id, symbol, interval_code, open_time, close_time, open_price, high_price, low_price, close_price, volume, number_of_trades, closed, ingestion_source, created_at, updated_at FROM crypto_ai.candle WHERE symbol = 'EGLDUSDT' AND ((interval_code = '1m' AND open_time BETWEEN '2026-10-11 22:36:00' AND '2026-10-11 22:45:00') OR (interval_code = '5m' AND open_time BETWEEN '2026-10-11 22:25:00' AND '2026-10-11 22:40:00')) ORDER BY interval_code, open_time;